  "LO-359": {
    "title": "Diplomatic Dialogue: Formulaic Expressions & Nuanced Debate 💬🤝",
    "desc": "Uses formulaic/polite expressions to communicate such as 'May I borrow your book?', 'I would like to differ' etc.",
    "subSkill": "Conversation & Polite Expressions",
    "audio_script": "During a Mock United Nations (MUN) simulation, Kabir practices diplomatic phrases to voice respectful disagreement during committee proceedings.",
    "story": "During a Mock United Nations (MUN) simulation, Kabir practices diplomatic phrases to voice respectful disagreement during committee proceedings.",
    "instructions": [],
    "questions": [
      {
        "q": "Which formulaic phrase expresses professional, courteous disagreement without causing personal offense?",
        "options": [
          "'Sit down and be quiet!'",
          "'Your idea is the worst idea ever.'",
          "'You are completely wrong and clueless!'",
          "'I respect the delegate's perspective; however, I would like to offer a different viewpoint based on recent trade data.'"
        ],
        "answer": 3,
        "explain": "Diplomatic phrases acknowledge the counterpart's point while introducing counter-evidence with professional grace!"
      },
      {
        "q": "What is the polite, formal phrase used to interrupt a committee speaker when asking a procedural question in formal assemblies?",
        "options": [
          "'Turn off their microphone!'",
          "'Excuse me, listen to me instead!'",
          "'Hey stop talking right now!'",
          "'Point of Information, Mr. Chairperson.'"
        ],
        "answer": 3,
        "explain": "'Point of Information' or 'Point of Order' follows established parliamentary rules of order."
      },
      {
        "q": "Why are diplomatic linguistic formulas ('If I may add', 'With all due respect', 'I beg to differ') essential in statecraft and business?",
        "options": [
          "Because speaking plainly is forbidden",
          "To make meetings take twelve hours",
          "They de-escalate emotional friction, preserve working relationships, and focus negotiations on objective policy solutions",
          "To confuse foreign delegates"
        ],
        "answer": 2,
        "explain": "Polite protocol prevents personal animosity from derailing vital geopolitical and commercial pacts."
      }
    ]
  },
