  "LO-367": {
    "title": "Grammar Arena: Sentence Auctions & Structural Games 🎲🏆",
    "desc": "Participates in grammar games and kinaesthetic activities for language learning",
    "subSkill": "Grammar in Use",
    "audio_script": "In a fast-paced 'Sentence Auction' game, student teams bid token coins on sentences, competing to spot hidden grammatical errors in parallelism and modifier placement.",
    "story": "In a fast-paced 'Sentence Auction' game, student teams bid token coins on sentences, competing to spot hidden grammatical errors in parallelism and modifier placement.",
    "instructions": [],
    "questions": [
      {
        "q": "Identify the 'DANGLING MODIFIER' error: 'Walking through the ancient forest, the giant oak tree came into view.' Why is this grammatically flawed?",
        "options": [
          "It implies that the oak tree itself was walking! The modifier 'Walking through the ancient forest' must modify the human observer, not the tree",
          "The sentence has no verb",
          "Oak trees cannot be in forests",
          "It needs three exclamation marks"
        ],
        "answer": 0,
        "explain": "Correction: 'Walking through the ancient forest, I SAW the giant oak tree come into view.' Modifiers must attach to the true subject!"
      },
      {
        "q": "Which sentence maintains flawless PARALLEL STRUCTURE in its series of predicates?",
        "options": [
          "Maya loves hiking rugged trails, kayaking roaring rivers, and photographing wildlife.",
          "Maya loves to hike, kayaking, and photograph.",
          "Maya loves hiking rugged trails, to kayak roaring rivers, and photos.",
          "Maya loves hiking, kayaking, and to take pictures."
        ],
        "answer": 0,
        "explain": "Parallel structure pairs matching grammatical forms: hiking..., kayaking..., and photographing... (all gerunds)!"
      },
      {
        "q": "In the classroom 'Grammar Freeze Relay Game', the teacher shouts: 'Freeze and shout an ACTION VERB!' Which student shouts the correct action verb to score a winning point?",
        "options": [
          "Meera shouts: 'Under!'",
          "Arjun shouts: 'Sprint!'",
          "Kavita shouts: 'Purple!'",
          "Rohit shouts: 'Carefully!'"
        ],
        "answer": 1,
        "explain": "'Sprint' is a vibrant action verb showing physical movement, scoring the winning point in the active grammar game!"
      }
    ]
  },
