  "LO-378": {
    "title": "Polynomial Multiplication: Expanding Binomials & Trinomials 🧮✖️",
    "desc": "Multiplies algebraic expressions (e.g., expands (2x-5)(3x²+7))",
    "subSkill": "Variables & Algebraic Expressions",
    "audio_script": "Students multiply multi-term algebraic expressions by applying the distributive property systematically to every term.",
    "story": "Students multiply multi-term algebraic expressions by applying the distributive property systematically to every term.",
    "instructions": [],
    "questions": [
      {
        "q": "Expand the product of the binomials: (2x - 5)(3x + 4) = 2x(3x + 4) - 5(3x + 4) =",
        "options": [
          "6x² + 7x - 20",
          "5x² - 7x - 20",
          "6x² - 20",
          "6x² - 7x - 20 (6x² + 8x - 15x - 20 = 6x² - 7x - 20)"
        ],
        "answer": 3,
        "explain": "FOIL method: First (6x²), Outside (+8x), Inside (-15x), Last (-20). Combining like terms: 6x² - 7x - 20!"
      },
      {
        "q": "Expand: (x + 3)(x² - 3x + 9) =",
        "options": [
          "x³ - 6x² + 27",
          "x³ + 27 (Sum of cubes identity: (a+b)(a²-ab+b²) = a³ + b³)",
          "x³ - 27",
          "x³ + 9x + 27"
        ],
        "answer": 1,
        "explain": "All middle cross-terms cancel out, yielding the famous sum of cubes: x³ + 3³ = x³ + 27!"
      },
      {
        "q": "What is the degree of the polynomial: 5x⁴ - 3x² + 7x - 9?",
        "options": [
          "Degree 2",
          "Degree 1",
          "Degree 5",
          "Degree 4 (the highest exponent of the variable 'x')"
        ],
        "answer": 3,
        "explain": "The degree of a single-variable polynomial is determined by the highest power of the variable (4)!"
      }
    ]
  },
