  "LO-379": {
    "title": "Equation Wizards: Daily Life Puzzle Solvers 🧩⚖️",
    "desc": "Solves puzzles and daily life problems using variables",
    "subSkill": "Variables & Algebraic Expressions",
    "audio_script": "Rohan's mother is three times as old as Rohan. In 12 years, she will be twice as old as Rohan will be then. Let's find Rohan's present age (x).",
    "story": "Rohan's mother is three times as old as Rohan. In 12 years, she will be twice as old as Rohan will be then. Let's find Rohan's present age (x).",
    "instructions": [],
    "questions": [
      {
        "q": "Set up the equation: Mother's age = 3x. In 12 years: (3x + 12) = 2(x + 12). Solve for Rohan's present age 'x':",
        "options": [
          "x = 8 years old",
          "x = 15 years old",
          "x = 10 years old",
          "x = 12 years old (3x + 12 = 2x + 24 -> 3x - 2x = 24 - 12 -> x = 12)"
        ],
        "answer": 3,
        "explain": "3x + 12 = 2x + 24. Subtract 2x and 12 from both sides: x = 12 years old (Mother is 36)!"
      },
      {
        "q": "The sum of three consecutive EVEN integers is 54. Let the integers be x, x+2, x+4. What is the smallest integer 'x'?",
        "options": [
          "x = 12",
          "x = 18",
          "x = 16 (3x + 6 = 54 -> 3x = 48 -> x = 16; integers are 16, 18, 20)",
          "x = 14"
        ],
        "answer": 2,
        "explain": "3x + 6 = 54 -> 3x = 48 -> x = 16. Verify: 16 + 18 + 20 = 54!"
      },
      {
        "q": "A piggy bank contains ₹370 in ₹5 and ₹10 notes. If there are 50 notes in total, how many ₹10 notes are there?",
        "options": [
          "30 notes",
          "26 notes",
          "20 notes",
          "24 notes (Let ten-rupee notes = n. 10n + 5(50 - n) = 370 -> 5n + 250 = 370 -> 5n = 120 -> n = 24)"
        ],
        "answer": 3,
        "explain": "24 ten-rupee notes (₹240) + 26 five-rupee notes (₹130) = ₹370 total!"
      }
    ]
  },
