  "LO-381": {
    "title": "Empirical Probability: Coin Tosses & Law of Large Numbers 🪙🎲",
    "desc": "Makes hypotheses on chances of future events on the basis of earlier occurrences or available data (e.g., repeated throws of dice and coins)",
    "subSkill": "Probability & Chance",
    "audio_script": "Students perform a probability experiment: tossing a coin 1,000 times on a computer simulator to track the experimental frequency of Heads.",
    "story": "Students perform a probability experiment: tossing a coin 1,000 times on a computer simulator to track the experimental frequency of Heads.",
    "instructions": [],
    "questions": [
      {
        "q": "If a coin is tossed 10 times, you might get 7 Heads (70%). What does the LAW OF LARGE NUMBERS predict as the number of tosses reaches 10,000?",
        "options": [
          "The coin will land on its edge",
          "Tails will become 100%",
          "Heads will disappear completely",
          "The experimental relative frequency will converge extremely close to the theoretical probability of 0.5 (50%)"
        ],
        "answer": 3,
        "explain": "As the number of independent trials increases, the empirical frequency inexorably approaches theoretical probability!"
      },
      {
        "q": "What is the probability of rolling a SUM OF 7 when rolling two fair standard six-sided dice simultaneously?",
        "options": [
          "1/12",
          "6/36 = 1/6 (favorable pairs: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1))",
          "7/36",
          "1/2"
        ],
        "answer": 1,
        "explain": "There are 6 combinations summing to 7 out of 36 total possible pairs: 6/36 = 1/6!"
      },
      {
        "q": "What is the probability of an IMPOSSIBLE EVENT (e.g., rolling an 8 on a standard 6-sided die)?",
        "options": [
          "0 (Zero probability)",
          "1",
          "-1",
          "0.5"
        ],
        "answer": 0,
        "explain": "Impossible events have a probability of 0, while certain events have a probability of 1!"
      }
    ]
  },
