  "LO-385": {
    "title": "Quadrilateral Angles: Angle Sum Property Proof 📐🔷",
    "desc": "Solves problems related to angles of a quadrilateral using angle sum property",
    "subSkill": "Quadrilaterals",
    "audio_script": "In quadrilateral ABCD, three angles measure 70°, 80°, and 120°. Kabir needs to calculate the fourth missing angle 'x'.",
    "story": "In quadrilateral ABCD, three angles measure 70°, 80°, and 120°. Kabir needs to calculate the fourth missing angle 'x'.",
    "instructions": [],
    "questions": [
      {
        "q": "Calculate the missing angle 'x' in quadrilateral ABCD: 70° + 80° + 120° + x = 360°:",
        "options": [
          "80°",
          "100°",
          "90° (70 + 80 + 120 = 270; 360 - 270 = 90°)",
          "110°"
        ],
        "answer": 2,
        "explain": "The sum of all four interior angles in any quadrilateral is 360°! 360° - 270° = 90°."
      },
      {
        "q": "Why is the sum of angles in ANY polygon with 'n' sides given by the formula (n - 2) x 180°?",
        "options": [
          "Because circles have 360 degrees",
          "Any n-sided polygon can be triangulated into (n - 2) non-overlapping triangles from one vertex, each contributing 180°",
          "Because 360 is a magic number",
          "It is only a rough guess"
        ],
        "answer": 1,
        "explain": "A quadrilateral (n=4) splits into 4 - 2 = 2 triangles (2 x 180° = 360°); a pentagon (n=5) into 3 triangles (540°)!"
      },
      {
        "q": "What is the measure of each interior angle in a REGULAR PENTAGON (5 equal sides and 5 equal angles)? Formula: (5-2)x180° / 5 =",
        "options": [
          "100°",
          "120°",
          "108° (540° / 5 = 108°)",
          "90°"
        ],
        "answer": 2,
        "explain": "Total sum = 3 x 180° = 540°. Dividing by 5 equal angles gives 108° for every corner!"
      }
    ]
  },
