    "desc": "Estimates the area of shapes like trapezium and other polygons using square grid/graph sheet and verifies using formulas",
    "subSkill": "Perimeter & Area",
    "audio_script": "A highway embankment cross-section is shaped like a trapezium with parallel bases measuring a = 12 meters and b = 8 meters, with perpendicular height h = 5 meters.",
