  "LO-392": {
    "title": "Divisibility Detectives: Proving Rules of 3, 9 and 11 🕵️‍♂️🔢",
    "desc": "Proves divisibility rules of 2, 3, 4, 5, 6, 9 and 11",
    "subSkill": "Factors, Multiples & Divisibility",
    "audio_script": "A computer programmer tests whether large barcode numbers are divisible by 3, 9, or 11 without performing long division.",
    "story": "A computer programmer tests whether large barcode numbers are divisible by 3, 9, or 11 without performing long division.",
    "instructions": [],
    "questions": [
      {
        "q": "What is the mathematical DIVISIBILITY RULE FOR 9?",
        "options": [
          "A number is divisible by 9 if and only if the SUM of its digits is divisible by 9",
          "The first digit must be 9",
          "The number must be odd",
          "The number must end in 9"
        ],
        "answer": 0,
        "explain": "Because 10 ≡ 1 (mod 9), any number has the same remainder as the sum of its digits!"
      },
      {
        "q": "What is the DIVISIBILITY RULE FOR 11? Test the number 1,364:",
        "options": [
          "Divide by 2 and add 1",
          "The number has four digits",
          "The difference between the sum of digits at odd places and sum of digits at even places is 0 or a multiple of 11: (1+6) - (3+4) = 7 - 7 = 0 (Divisible!)",
          "The number must end in 1"
        ],
        "answer": 2,
        "explain": "Sum at odd places (1+6=7) minus sum at even places (3+4=7) = 0. Since 0 is divisible by 11, 1,364 is divisible by 11!"
      },
      {
        "q": "Which of these numbers is divisible by 6 (must be divisible by BOTH 2 and 3)?",
        "options": [
          "435 (odd number)",
          "431",
          "430 (sum 4+3+0 = 7, not divisible by 3)",
          "432 (ends in even 2, and sum 4+3+2 = 9 is divisible by 3)"
        ],
        "answer": 3,
        "explain": "432 is even (divisible by 2) and its digits sum to 9 (divisible by 3). Therefore, it is divisible by 6!"
      }
    ]
  },
