  "LO-394": {
    "title": "Axioms of Arithmetic: Commutative, Associative & Distributive Laws 🏛️🧮",
    "desc": "Generalises properties of addition, subtraction, multiplication and division of rational numbers through patterns",
    "subSkill": "Fractions, Decimals & Rational Numbers",
    "audio_script": "Students generalize algebraic properties across rational numbers: addition and multiplication are closed, commutative, associative, and distributive.",
    "story": "Students generalize algebraic properties across rational numbers: addition and multiplication are closed, commutative, associative, and distributive.",
    "instructions": [],
    "questions": [
      {
        "q": "What property of multiplication over addition is represented by: a x (b + c) = (a x b) + (a x c)?",
        "options": [
          "The DISTRIBUTIVE PROPERTY of multiplication over addition",
          "The Commutative Property",
          "The Associative Property",
          "The Closure Property"
        ],
        "answer": 0,
        "explain": "The Distributive Property allows multiplying a factor across all terms inside parentheses!"
      },
      {
        "q": "Which operation on rational numbers is NOT commutative (i.e., a ○ b ≠ b ○ a)?",
        "options": [
          "Addition (a + b = b + a)",
          "Multiplication (a x b = b x a)",
          "All operations are commutative",
          "Subtraction and Division (e.g., 5 - 3 ≠ 3 - 5; 8 ÷ 2 ≠ 2 ÷ 8)"
        ],
        "answer": 3,
        "explain": "5 - 3 = 2, but 3 - 5 = -2! Subtraction and division depend on order, so they are NOT commutative."
      },
      {
        "q": "What is the ADDITIVE INVERSE of the rational number -7/11 (the number you add to get 0)?",
        "options": [
          "0",
          "+11/7",
          "+7/11 (since -7/11 + 7/11 = 0)",
          "-11/7"
        ],
        "answer": 2,
        "explain": "The additive inverse of -x is +x, because their sum equals the additive identity zero!"
      }
    ]
  },
