  "LO-406": {
    "title": "Laws of Reflection: Optical Bench Measurements 🪞📐",
    "desc": "Measures angles of incidence and reflection, etc.",
    "subSkill": "Measurement & Calculation",
    "audio_script": "Using a ray box, plane mirror, and paper protractor, students measure the angles of incidence (∠i) and reflection (∠r) across 5 different trials.",
    "story": "Using a ray box, plane mirror, and paper protractor, students measure the angles of incidence (∠i) and reflection (∠r) across 5 different trials.",
    "instructions": [],
    "questions": [
      {
        "q": "What does the FIRST LAW OF REFLECTION state regarding the angle of incidence (∠i) and angle of reflection (∠r)?",
        "options": [
          "They always sum to 90°",
          "Angle of incidence is double the reflection",
          "Angle of reflection is always zero",
          "The angle of incidence is ALWAYS EQUAL to the angle of reflection (∠i = ∠r)"
        ],
        "answer": 3,
        "explain": "Fundamental optical law: ∠i = ∠r! If light strikes a mirror at 35° to the normal, it reflects off at exactly 35°."
      },
      {
        "q": "What is the 'NORMAL' in an optical reflection diagram?",
        "options": [
          "The ray of light itself",
          "The line showing the table",
          "A line parallel to the mirror",
          "An imaginary perpendicular line drawn at 90 degrees to the reflective mirror surface at the point of incidence"
        ],
        "answer": 3,
        "explain": "All reflection angles are measured relative to the perpendicular Normal line (90° to the mirror)!"
      },
      {
        "q": "How many multiple images will be formed of an object placed between two plane mirrors inclined at an angle of 90 degrees? Formula: Number of images n = (360° / θ) - 1",
        "options": [
          "2 images",
          "4 images",
          "3 images: (360 / 90) - 1 = 4 - 1 = 3 images",
          "Infinite images"
        ],
        "answer": 2,
        "explain": "n = (360/90) - 1 = 4 - 1 = 3 images! (When mirrors are parallel at 0°, n = infinity, as in barbershops)!"
      }
    ]
  },
