  "LO-408": {
    "title": "Friction & Adolescence: Applying Science to Life 🛞🧬",
    "desc": "Applies learning of scientific concepts in day-to-day life (purifying water, segregating wastes, increasing crop production, using metals/non-metals, friction, challenging myths and taboos about adolescence)",
    "subSkill": "Application of Concepts in Daily Life",
    "audio_script": "Students analyze why vehicle tires have deep tread grooves, why ball bearings reduce friction in machine axles, and debunk myths about teenage puberty.",
    "story": "Students analyze why vehicle tires have deep tread grooves, why ball bearings reduce friction in machine axles, and debunk myths about teenage puberty.",
    "instructions": [],
    "questions": [
      {
        "q": "Why are rubber tires of racing cars and buses engineered with deep tread patterns (grooves)?",
        "options": [
          "Treads channel away standing road water and increase surface interlocking grip (friction) to prevent dangerous skidding",
          "To make tires look fashionable",
          "To make the vehicle lighter",
          "Treads make tires spin without touching the road"
        ],
        "answer": 0,
        "explain": "Grooved treads dispel aquaplaning water films, ensuring high frictional contact between tire and pavement!"
      },
      {
        "q": "Why are steel BALL BEARINGS installed inside bicycle hubs and ceiling fan axles?",
        "options": [
          "To stop the axle from rotating",
          "To make fans heavier",
          "Rolling friction is vastly smaller than sliding friction, drastically reducing energy waste and wear",
          "To produce loud musical hums"
        ],
        "answer": 2,
        "explain": "Replacing sliding contact with smooth rolling spheres cuts kinetic friction down by up to 90%!"
      },
      {
        "q": "What endocrine gland, located at the base of the brain, is known as the 'Master Gland' because its hormones trigger puberty and govern other glands?",
        "options": [
          "The Thyroid Gland",
          "The Pancreas",
          "The Adrenal Gland",
          "The Pituitary Gland"
        ],
        "answer": 3,
        "explain": "The pituitary secretes growth hormone and gonadotropins, orchestrating adolescent physical metamorphosis!"
      }
    ]
  },
