    "desc": "Distinguishes the 'modern period' from the 'medieval' and 'ancient' periods through sources, nomenclature and broad developments",
    "subSkill": "Sources of History",
    "audio_script": "In 1817, British historian James Mill divided Indian history into 'Hindu', 'Muslim', and 'British' periods. Modern historians reject this communal division in favor of socio-economic milestones.",
