    "desc": "Analyses causes and consequences of marginalisation faced by disadvantaged sections of one's own region",
    "subSkill": "Constitution, Rights & Laws",
    "audio_script": "In civics class, students examine how forest evictions push indigenous Adivasi communities into urban migrant slums, stripping them of land, livelihood, and cultural heritage.",
